window.SCIENCE_DATA["physics"] = {"subject": "Physics", "questions": [{"id": 1, "topic": "Vectors", "difficulty": "Easy", "question": "Which of the following is a vector quantity?", "options": ["Speed", "Mass", "Displacement", "Temperature"], "answer": 2, "explanation": "Displacement has both magnitude and direction, making it a vector quantity. Speed, mass and temperature are scalar quantities."}, {"id": 2, "topic": "Vectors", "difficulty": "Medium", "question": "The resultant of two forces of 3 N and 4 N acting at right angles to each other is:", "options": ["5 N", "7 N", "1 N", "12 N"], "answer": 0, "explanation": "Using Pythagoras theorem: R = \u221a(3\u00b2 + 4\u00b2) = \u221a(9 + 16) = \u221a25 = 5 N."}, {"id": 3, "topic": "Vectors", "difficulty": "Medium", "question": "A vector of magnitude 10 N makes an angle of 30\u00b0 with the horizontal. Its horizontal component is:", "options": ["10 N", "8.66 N", "5 N", "17.32 N"], "answer": 1, "explanation": "Horizontal component = F cos \u03b8 = 10 cos 30\u00b0 = 10 \u00d7 0.866 = 8.66 N."}, {"id": 4, "topic": "Equilibrium", "difficulty": "Easy", "question": "For a body to be in equilibrium, the resultant force on it must be:", "options": ["Maximum", "Zero", "Equal to weight", "Directed upward"], "answer": 1, "explanation": "A body is in equilibrium when the net (resultant) force acting on it is zero. It is either at rest or moving with constant velocity."}, {"id": 5, "topic": "Equilibrium", "difficulty": "Medium", "question": "The principle of moments states that for equilibrium, the sum of clockwise moments about a point is:", "options": ["Greater than anticlockwise moments", "Equal to the sum of anticlockwise moments", "Zero", "Equal to the weight of the body"], "answer": 1, "explanation": "For rotational equilibrium, the sum of clockwise moments about any point must equal the sum of anticlockwise moments about the same point."}, {"id": 6, "topic": "Equilibrium", "difficulty": "Hard", "question": "A uniform metre rule of weight 1.5 N is pivoted at the 40 cm mark. A weight of 2.5 N is hung at the 10 cm mark. What weight must be hung at the 80 cm mark to balance the rule?", "options": ["1.0 N", "1.5 N", "2.0 N", "0.5 N"], "answer": 0, "explanation": "Clockwise moment = 1.5 \u00d7 (70 - 50) + W \u00d7 (80 - 40)... Actually taking moments about the 40 cm pivot: Clockwise = 1.5 \u00d7 10 + W \u00d7 40, Anticlockwise = 2.5 \u00d7 30. So 15 + 40W = 75, 40W = 60, W = 1.5 N. Hmm let me recalculate: Uniform rule centre at 50 cm. Pivot at 40 cm. Weight of rule acts at 50 cm (10 cm right of pivot). 2.5 N at 10 cm (30 cm left of pivot). Clockwise moment from rule weight = 1.5 \u00d7 10 = 15 Ncm. Anticlockwise = 2.5 \u00d7 30 = 75 Ncm. Need additional clockwise = 60 Ncm from weight at 80 cm = 40 cm from pivot. W = 60/40 = 1.5 N. But we need extra anticlockwise... wait. The rule weight gives clockwise. The 2.5N gives anticlockwise (larger). So we need more clockwise: 2.5 \u00d7 30 = 75 anticlockwise. Clockwise so far = 1.5 \u00d7 10 = 15. Need 60 more clockwise from 80cm mark which is 40cm from pivot: W = 60/40 = 1.5 N."}, {"id": 7, "topic": "Motion", "difficulty": "Easy", "question": "The slope of a velocity-time graph represents:", "options": ["Displacement", "Acceleration", "Distance", "Speed"], "answer": 1, "explanation": "The slope (gradient) of a velocity-time graph gives acceleration, because a = \u0394v/\u0394t."}, {"id": 8, "topic": "Motion", "difficulty": "Easy", "question": "A body moving with uniform acceleration has its velocity doubled in 4 s. If its initial velocity was 6 m/s, what is the acceleration?", "options": ["1.5 m/s\u00b2", "3 m/s\u00b2", "6 m/s\u00b2", "0.75 m/s\u00b2"], "answer": 0, "explanation": "a = (v - u)/t = (12 - 6)/4 = 6/4 = 1.5 m/s\u00b2."}, {"id": 9, "topic": "Motion", "difficulty": "Medium", "question": "A car accelerates from rest at 2 m/s\u00b2 for 10 s. The distance covered is:", "options": ["100 m", "50 m", "200 m", "20 m"], "answer": 0, "explanation": "Using s = ut + \u00bdat\u00b2 = 0 + \u00bd \u00d7 2 \u00d7 10\u00b2 = 100 m."}, {"id": 10, "topic": "Motion", "difficulty": "Hard", "question": "A stone is thrown vertically upward with a velocity of 20 m/s. (g = 10 m/s\u00b2). The maximum height reached is:", "options": ["20 m", "40 m", "10 m", "5 m"], "answer": 0, "explanation": "At max height v = 0. Using v\u00b2 = u\u00b2 - 2gs: 0 = 400 - 2(10)s, s = 400/20 = 20 m."}, {"id": 11, "topic": "Motion", "difficulty": "Medium", "question": "The distance travelled by a body in the nth second of its motion is given by:", "options": ["u + a(2n-1)/2", "u + a/2", "un + an\u00b2/2", "a/2"], "answer": 0, "explanation": "Sn = u + a(2n - 1)/2. This gives the distance covered in exactly the nth second."}, {"id": 12, "topic": "Light", "difficulty": "Easy", "question": "The bending of light as it passes from one medium to another is called:", "options": ["Reflection", "Refraction", "Diffraction", "Dispersion"], "answer": 1, "explanation": "Refraction is the change of direction of light when it passes from one medium to another due to change in speed."}, {"id": 13, "topic": "Light", "difficulty": "Medium", "question": "The refractive index of glass is 1.5. The speed of light in glass is (speed of light in vacuum = 3 \u00d7 10\u2078 m/s):", "options": ["3 \u00d7 10\u2078 m/s", "2 \u00d7 10\u2078 m/s", "4.5 \u00d7 10\u2078 m/s", "1.5 \u00d7 10\u2078 m/s"], "answer": 1, "explanation": "n = c/v, so v = c/n = (3 \u00d7 10\u2078)/1.5 = 2 \u00d7 10\u2078 m/s."}, {"id": 14, "topic": "Light", "difficulty": "Medium", "question": "When light travels from air to glass, it bends:", "options": ["Away from the normal", "Towards the normal", "Parallel to the normal", "In a random direction"], "answer": 1, "explanation": "Glass is optically denser than air, so light slows down and bends towards the normal when entering glass from air."}, {"id": 15, "topic": "Light", "difficulty": "Hard", "question": "The critical angle for a medium is 42\u00b0. Its refractive index is approximately:", "options": ["1.5", "1.33", "1.41", "2.0"], "answer": 0, "explanation": "n = 1/sin C = 1/sin 42\u00b0 = 1/0.669 = 1.49 \u2248 1.5."}, {"id": 16, "topic": "Waves", "difficulty": "Easy", "question": "Which of the following waves is longitudinal?", "options": ["Light wave", "Sound wave", "Water wave", "Radio wave"], "answer": 1, "explanation": "Sound waves are longitudinal because the particles vibrate parallel to the direction of wave propagation. Light, water and radio waves are transverse."}, {"id": 17, "topic": "Waves", "difficulty": "Easy", "question": "The frequency of a wave is 50 Hz. Its period is:", "options": ["0.02 s", "50 s", "0.5 s", "5 s"], "answer": 0, "explanation": "T = 1/f = 1/50 = 0.02 s."}, {"id": 18, "topic": "Waves", "difficulty": "Medium", "question": "A wave has a frequency of 200 Hz and a wavelength of 2 m. Its speed is:", "options": ["100 m/s", "400 m/s", "202 m/s", "40 m/s"], "answer": 1, "explanation": "v = f\u03bb = 200 \u00d7 2 = 400 m/s."}, {"id": 19, "topic": "Waves", "difficulty": "Medium", "question": "The property of waves that allows them to bend around obstacles is:", "options": ["Refraction", "Diffraction", "Polarisation", "Interference"], "answer": 1, "explanation": "Diffraction is the spreading or bending of waves as they pass through a narrow opening or around an edge/obstacle."}, {"id": 20, "topic": "Waves", "difficulty": "Hard", "question": "Two waves meet in phase. Wave A has amplitude 3 cm, Wave B has amplitude 5 cm. The amplitude of the resultant wave is:", "options": ["8 cm", "2 cm", "15 cm", "4 cm"], "answer": 0, "explanation": "When waves meet in phase (constructive interference), amplitudes add: 3 + 5 = 8 cm."}, {"id": 21, "topic": "Motion", "difficulty": "Medium", "question": "A bus travels 120 km in 2 hours. Its average speed is:", "options": ["60 km/h", "240 km/h", "30 km/h", "120 km/h"], "answer": 0, "explanation": "Average speed = total distance / total time = 120/2 = 60 km/h."}, {"id": 22, "topic": "Vectors", "difficulty": "Hard", "question": "A force of 6 N acts due East and another of 8 N acts due North. The magnitude of the resultant is:", "options": ["14 N", "10 N", "48 N", "2 N"], "answer": 1, "explanation": "R = \u221a(6\u00b2 + 8\u00b2) = \u221a(36 + 64) = \u221a100 = 10 N."}, {"id": 23, "topic": "Waves", "difficulty": "Easy", "question": "In a transverse wave, particle vibration is:", "options": ["Parallel to wave direction", "Perpendicular to wave direction", "In circular motion", "At random"], "answer": 1, "explanation": "In transverse waves, particles vibrate perpendicular (at right angles) to the direction of energy transfer."}, {"id": 24, "topic": "Light", "difficulty": "Easy", "question": "The image formed by a plane mirror is:", "options": ["Real and inverted", "Virtual and erect", "Real and erect", "Virtual and inverted"], "answer": 1, "explanation": "A plane mirror forms a virtual, erect (upright) image that is the same size as the object and laterally inverted."}, {"id": 25, "topic": "Equilibrium", "difficulty": "Easy", "question": "Which condition is NOT required for a body in equilibrium?", "options": ["Resultant force is zero", "Resultant moment is zero", "Body must be at rest", "Sum of clockwise moments equals anticlockwise moments"], "answer": 2, "explanation": "A body can be in equilibrium while moving with constant velocity (dynamic equilibrium). It does not have to be at rest."}]};
window.SCIENCE_DATA["chemistry"] = {"subject": "Chemistry", "questions": [{"id": 1, "topic": "Particulate Nature of Matter", "difficulty": "Easy", "question": "The smallest particle of an element that retains its chemical properties is:", "options": ["Molecule", "Atom", "Compound", "Ion"], "answer": 1, "explanation": "An atom is the smallest particle of an element that retains all the chemical properties of that element."}, {"id": 2, "topic": "Particulate Nature of Matter", "difficulty": "Easy", "question": "Which postulate of the kinetic molecular theory states that particles are in constant random motion?", "options": ["Particles have negligible volume", "Particles are in constant random motion", "Particles attract each other", "Temperature is proportional to kinetic energy"], "answer": 1, "explanation": "The kinetic molecular theory states that all particles of matter are in constant, rapid, random motion."}, {"id": 3, "topic": "Particulate Nature of Matter", "difficulty": "Medium", "question": "The process by which a solid changes directly to a gas without passing through the liquid state is called:", "options": ["Evaporation", "Sublimation", "Distillation", "Boiling"], "answer": 1, "explanation": "Sublimation is the direct change of state from solid to gas. Examples include iodine and dry ice (solid CO\u2082)."}, {"id": 4, "topic": "Particulate Nature of Matter", "difficulty": "Medium", "question": "Diffusion is best described as:", "options": ["Movement of particles from low to high concentration", "Random movement of particles from high to low concentration until evenly distributed", "A chemical reaction between gases", "The evaporation of a liquid"], "answer": 1, "explanation": "Diffusion is the net movement of particles from a region of higher concentration to a region of lower concentration due to random motion."}, {"id": 5, "topic": "Particulate Nature of Matter", "difficulty": "Hard", "question": "Which of the following will diffuse fastest?", "options": ["Oxygen (O\u2082)", "Chlorine (Cl\u2082)", "Carbon dioxide (CO\u2082)", "Hydrogen (H\u2082)"], "answer": 3, "explanation": "According to Graham's law, the rate of diffusion is inversely proportional to the square root of the molar mass. Hydrogen has the lowest molar mass (2 g/mol) so it diffuses fastest."}, {"id": 6, "topic": "Periodic Table", "difficulty": "Easy", "question": "Elements in the same group of the periodic table have the same:", "options": ["Number of shells", "Atomic mass", "Number of valence electrons", "Number of neutrons"], "answer": 2, "explanation": "Elements in the same group (column) have the same number of valence electrons, which gives them similar chemical properties."}, {"id": 7, "topic": "Periodic Table", "difficulty": "Easy", "question": "How many periods are in the periodic table?", "options": ["7", "8", "18", "10"], "answer": 0, "explanation": "There are 7 periods (rows) in the periodic table, corresponding to the number of electron shells."}, {"id": 8, "topic": "Periodic Table", "difficulty": "Medium", "question": "Which element is in Group 14, Period 3?", "options": ["Carbon", "Silicon", "Germanium", "Tin"], "answer": 1, "explanation": "Silicon (Si) has atomic number 14 and is in Group 14, Period 3. Carbon is Period 2, Germanium Period 4, Tin Period 5."}, {"id": 9, "topic": "Periodic Table", "difficulty": "Medium", "question": "The most electronegative element in the periodic table is:", "options": ["Oxygen", "Chlorine", "Fluorine", "Nitrogen"], "answer": 2, "explanation": "Fluorine is the most electronegative element with a value of 4.0 on the Pauling scale."}, {"id": 10, "topic": "Periodic Table", "difficulty": "Hard", "question": "Which of the following orders correctly shows increasing atomic radius?", "options": ["Na < Mg < Al", "Al < Mg < Na", "Mg < Na < Al", "Na < Al < Mg"], "answer": 1, "explanation": "Across a period (Na \u2192 Mg \u2192 Al), atomic radius decreases because effective nuclear charge increases, pulling electrons closer. So Al < Mg < Na."}, {"id": 11, "topic": "Chemical Bonding", "difficulty": "Easy", "question": "The bond formed by the sharing of electron pairs between two atoms is:", "options": ["Ionic bond", "Covalent bond", "Metallic bond", "Hydrogen bond"], "answer": 1, "explanation": "In covalent bonding, atoms share pairs of electrons to achieve a stable electron configuration."}, {"id": 12, "topic": "Chemical Bonding", "difficulty": "Easy", "question": "An ionic bond is formed between:", "options": ["Two non-metals", "A metal and a non-metal", "Two metals", "Two noble gases"], "answer": 1, "explanation": "Ionic bonds form when a metal transfers electrons to a non-metal, creating oppositely charged ions that attract each other."}, {"id": 13, "topic": "Chemical Bonding", "difficulty": "Medium", "question": "The electron dot structure of HCl shows:", "options": ["Ionic bond with H\u207a and Cl\u207b", "One shared pair and three lone pairs on Cl", "Two shared pairs", "No lone pairs"], "answer": 1, "explanation": "HCl has a single covalent bond (one shared electron pair) with H, and the chlorine atom has three lone pairs (6 non-bonding electrons)."}, {"id": 14, "topic": "Chemical Bonding", "difficulty": "Medium", "question": "Which molecule has a double bond between its atoms?", "options": ["H\u2082", "O\u2082", "N\u2082", "Cl\u2082"], "answer": 1, "explanation": "O\u2082 has a double bond (O=O). H\u2082 and Cl\u2082 have single bonds, N\u2082 has a triple bond."}, {"id": 15, "topic": "Chemical Bonding", "difficulty": "Hard", "question": "The shape of the methane (CH\u2084) molecule according to VSEPR theory is:", "options": ["Trigonal planar", "Tetrahedral", "Bent", "Linear"], "answer": 1, "explanation": "CH\u2084 has 4 bonding pairs and 0 lone pairs on the central carbon, giving a tetrahedral shape with bond angles of 109.5\u00b0."}, {"id": 16, "topic": "Acids and Bases", "difficulty": "Easy", "question": "A substance with a pH of 3 is:", "options": ["Strongly acidic", "Neutral", "Strongly alkaline", "Slightly alkaline"], "answer": 0, "explanation": "pH below 7 indicates acidity. pH 3 is strongly acidic (far from neutral pH 7)."}, {"id": 17, "topic": "Acids and Bases", "difficulty": "Easy", "question": "Which of the following is a strong acid?", "options": ["CH\u2083COOH", "HCl", "NH\u2083", "NaOH"], "answer": 1, "explanation": "HCl (hydrochloric acid) is a strong acid that ionizes completely in water. CH\u2083COOH is a weak acid, NH\u2083 is a base, and NaOH is a strong base."}, {"id": 18, "topic": "Acids and Bases", "difficulty": "Medium", "question": "The reaction between an acid and a base to form salt and water is called:", "options": ["Decomposition", "Neutralisation", "Displacement", "Oxidation"], "answer": 1, "explanation": "Neutralisation: Acid + Base \u2192 Salt + Water. For example, HCl + NaOH \u2192 NaCl + H\u2082O."}, {"id": 19, "topic": "Acids and Bases", "difficulty": "Medium", "question": "A salt formed by the partial replacement of replaceable hydrogen ions in an acid is:", "options": ["Normal salt", "Acid salt", "Basic salt", "Double salt"], "answer": 1, "explanation": "An acid salt is formed by partial neutralisation of an acid, e.g., NaHSO\u2084 from H\u2082SO\u2084 + NaOH."}, {"id": 20, "topic": "Acids and Bases", "difficulty": "Hard", "question": "What is the pH of a 0.001 M HCl solution?", "options": ["1", "3", "11", "0.001"], "answer": 1, "explanation": "HCl is a strong acid, so [H\u207a] = 0.001 = 10\u207b\u00b3 M. pH = -log(10\u207b\u00b3) = 3."}, {"id": 21, "topic": "Organic Introduction", "difficulty": "Easy", "question": "The general formula for alkanes is:", "options": ["C\u2099H\u2082\u2099", "C\u2099H\u2082\u2099\u208a\u2082", "C\u2099H\u2082\u2099\u208b\u2082", "C\u2099H\u2099"], "answer": 1, "explanation": "Alkanes are saturated hydrocarbons with the general formula C\u2099H\u2082\u2099\u208a\u2082. Examples: CH\u2084 (methane), C\u2082H\u2086 (ethane)."}, {"id": 22, "topic": "Organic Introduction", "difficulty": "Easy", "question": "Which of the following is an alkene?", "options": ["Methane", "Ethene", "Ethane", "Propane"], "answer": 1, "explanation": "Ethene (C\u2082H\u2084) is an alkene with a carbon-carbon double bond. The general formula for alkenes is C\u2099H\u2082\u2099."}, {"id": 23, "topic": "Organic Introduction", "difficulty": "Medium", "question": "The IUPAC name for CH\u2083CH\u2082CH\u2082OH is:", "options": ["Methanol", "Ethanol", "Propan-1-ol", "Butanol"], "answer": 2, "explanation": "The compound has 3 carbon atoms (prop-) with an -OH group on carbon 1: Propan-1-ol."}, {"id": 24, "topic": "Particulate Nature of Matter", "difficulty": "Hard", "question": "Which statement about the arrangement of particles in solids, liquids, and gases is correct?", "options": ["Solids have particles that are far apart and move freely", "Liquids have particles that are closely packed but can slide over each other", "Gases have particles that are arranged in a fixed pattern", "In all states, particles are stationary"], "answer": 1, "explanation": "In liquids, particles are close together but can move past each other, giving liquids a definite volume but no definite shape."}, {"id": 25, "topic": "Chemical Bonding", "difficulty": "Medium", "question": "Metallic bonding involves:", "options": ["Sharing of electrons between two non-metals", "Electrostatic attraction between metal cations and delocalised electrons", "Transfer of electrons from metal to non-metal", "Attraction between permanent dipoles"], "answer": 1, "explanation": "In metallic bonding, positive metal ions (cations) are held together by a 'sea' of delocalised (free-moving) electrons."}]};
window.SCIENCE_DATA["biology"] = {"subject": "Biology", "questions": [{"id": 1, "topic": "Cell", "difficulty": "Easy", "question": "Which organelle is known as the 'powerhouse of the cell'?", "options": ["Nucleus", "Ribosome", "Mitochondrion", "Golgi apparatus"], "answer": 2, "explanation": "The mitochondrion is called the powerhouse of the cell because it is the site of aerobic respiration, producing ATP (energy) for the cell."}, {"id": 2, "topic": "Cell", "difficulty": "Easy", "question": "The structure that controls the movement of substances in and out of the cell is:", "options": ["Cell wall", "Cell membrane", "Cytoplasm", "Vacuole"], "answer": 1, "explanation": "The cell membrane (plasma membrane) is selectively permeable and controls what enters and leaves the cell."}, {"id": 3, "topic": "Cell", "difficulty": "Medium", "question": "Which structure is found in plant cells but NOT in animal cells?", "options": ["Mitochondrion", "Nucleus", "Chloroplast", "Ribosome"], "answer": 2, "explanation": "Chloroplasts are found only in plant cells (and algae). They contain chlorophyll for photosynthesis. Both cell types have mitochondria, nuclei and ribosomes."}, {"id": 4, "topic": "Cell", "difficulty": "Medium", "question": "The site of protein synthesis in the cell is the:", "options": ["Lysosome", "Ribosome", "Vacuole", "Centrosome"], "answer": 1, "explanation": "Ribosomes are the sites where amino acids are assembled into proteins based on instructions from mRNA."}, {"id": 5, "topic": "Cell", "difficulty": "Hard", "question": "A cell has 46 chromosomes. After mitosis, each daughter cell will have:", "options": ["23 chromosomes", "46 chromosomes", "92 chromosomes", "12 chromosomes"], "answer": 1, "explanation": "Mitosis produces genetically identical daughter cells with the same chromosome number as the parent cell (46 in humans). Meiosis would halve it to 23."}, {"id": 6, "topic": "Tissues", "difficulty": "Easy", "question": "A group of cells with similar structure and performing the same function is called a:", "options": ["Organ", "Tissue", "System", "Organelle"], "answer": 1, "explanation": "A tissue is a group of similar cells working together to perform a specific function, e.g., muscle tissue, epithelial tissue."}, {"id": 7, "topic": "Tissues", "difficulty": "Easy", "question": "Which tissue is responsible for the contraction and movement of body parts?", "options": ["Epithelial tissue", "Connective tissue", "Muscle tissue", "Nervous tissue"], "answer": 2, "explanation": "Muscle tissue contains fibres that can contract, producing movement. There are three types: skeletal, cardiac, and smooth muscle."}, {"id": 8, "topic": "Tissues", "difficulty": "Medium", "question": "Blood is classified as which type of tissue?", "options": ["Epithelial", "Connective", "Muscular", "Nervous"], "answer": 1, "explanation": "Blood is a fluid connective tissue. It connects and transports substances between different parts of the body."}, {"id": 9, "topic": "Tissues", "difficulty": "Medium", "question": "The tissue that lines body surfaces and organs is:", "options": ["Connective tissue", "Epithelial tissue", "Muscle tissue", "Nervous tissue"], "answer": 1, "explanation": "Epithelial tissue covers body surfaces (skin), lines cavities, and forms glands. It provides protection and facilitates absorption/secretion."}, {"id": 10, "topic": "Tissues", "difficulty": "Hard", "question": "Which plant tissue is responsible for transporting water from roots to leaves?", "options": ["Phloem", "Xylem", "Cambium", "Epidermis"], "answer": 1, "explanation": "Xylem transports water and dissolved minerals upward from roots to leaves. Phloem transports manufactured food (sugars) from leaves to other parts."}, {"id": 11, "topic": "Photosynthesis", "difficulty": "Easy", "question": "The raw materials needed for photosynthesis are:", "options": ["Glucose and oxygen", "Carbon dioxide and water", "Nitrogen and water", "Oxygen and minerals"], "answer": 1, "explanation": "Photosynthesis requires carbon dioxide (CO\u2082) and water (H\u2082O), which are converted into glucose and oxygen using light energy."}, {"id": 12, "topic": "Photosynthesis", "difficulty": "Easy", "question": "The equation for photosynthesis is:", "options": ["6CO\u2082 + 6H\u2082O \u2192 C\u2086H\u2081\u2082O\u2086 + 6O\u2082", "C\u2086H\u2081\u2082O\u2086 + 6O\u2082 \u2192 6CO\u2082 + 6H\u2082O", "6O\u2082 + 6H\u2082O \u2192 6CO\u2082 + 6H\u2082O", "6CO\u2082 + 6O\u2082 \u2192 C\u2086H\u2081\u2082O\u2086 + 6H\u2082O"], "answer": 0, "explanation": "Photosynthesis: 6CO\u2082 + 6H\u2082O --(light/chlorophyll)--> C\u2086H\u2081\u2082O\u2086 + 6O\u2082. Note this is the reverse of respiration."}, {"id": 13, "topic": "Photosynthesis", "difficulty": "Medium", "question": "Which pigment absorbs light energy for photosynthesis?", "options": ["Carotene", "Xanthophyll", "Chlorophyll", "Anthocyanin"], "answer": 2, "explanation": "Chlorophyll (mainly chlorophyll a) is the primary photosynthetic pigment, absorbing mainly red and blue-violet light and reflecting green light."}, {"id": 14, "topic": "Photosynthesis", "difficulty": "Medium", "question": "Photosynthesis takes place mainly in which part of the leaf?", "options": ["Epidermis", "Mesophyll layer", "Veins", "Cuticle"], "answer": 1, "explanation": "The mesophyll layer contains the highest concentration of chloroplasts and is the main site of photosynthesis."}, {"id": 15, "topic": "Photosynthesis", "difficulty": "Hard", "question": "The light-dependent reactions of photosynthesis occur in the:", "options": ["Stroma", "Thylakoid membranes", "Outer membrane", "Intermembrane space"], "answer": 1, "explanation": "Light-dependent reactions occur on the thylakoid membranes where chlorophyll absorbs light. The Calvin cycle (light-independent) occurs in the stroma."}, {"id": 16, "topic": "Respiratory System", "difficulty": "Easy", "question": "The organ responsible for gaseous exchange in humans is the:", "options": ["Heart", "Kidney", "Lung", "Liver"], "answer": 2, "explanation": "The lungs are the primary organs of respiration where oxygen enters the blood and carbon dioxide is removed."}, {"id": 17, "topic": "Respiratory System", "difficulty": "Easy", "question": "During inhalation, the diaphragm:", "options": ["Relaxes and moves upward", "Contracts and moves downward", "Remains stationary", "Moves sideways"], "answer": 1, "explanation": "During inhalation, the diaphragm contracts and flattens (moves downward), increasing the volume of the thoracic cavity and decreasing pressure, drawing air in."}, {"id": 18, "topic": "Respiratory System", "difficulty": "Medium", "question": "The smallest air sacs in the lungs where gas exchange occurs are called:", "options": ["Bronchi", "Bronchioles", "Alveoli", "Trachea"], "answer": 2, "explanation": "Alveoli are tiny, thin-walled air sacs surrounded by capillaries. Their large surface area and thin walls allow efficient gas exchange."}, {"id": 19, "topic": "Respiratory System", "difficulty": "Medium", "question": "Which gas is taken into the blood at the alveoli?", "options": ["Carbon dioxide", "Nitrogen", "Oxygen", "Hydrogen"], "answer": 2, "explanation": "At the alveoli, oxygen diffuses from the air in the alveoli into the blood capillaries (higher concentration in alveoli), while CO\u2082 diffuses out."}, {"id": 20, "topic": "Respiratory System", "difficulty": "Hard", "question": "The equation for aerobic respiration is:", "options": ["6CO\u2082 + 6H\u2082O \u2192 C\u2086H\u2081\u2082O\u2086 + 6O\u2082", "C\u2086H\u2081\u2082O\u2086 + 6O\u2082 \u2192 6CO\u2082 + 6H\u2082O + energy", "C\u2086H\u2081\u2082O\u2086 \u2192 2C\u2082H\u2085OH + 2CO\u2082 + energy", "C\u2086H\u2081\u2082O\u2086 \u2192 2Pyruvic acid + energy"], "answer": 1, "explanation": "Aerobic respiration: C\u2086H\u2081\u2082O\u2086 + 6O\u2082 \u2192 6CO\u2082 + 6H\u2082O + energy (ATP). This occurs in the mitochondria."}, {"id": 21, "topic": "Ecology", "difficulty": "Easy", "question": "Organisms that produce their own food through photosynthesis are called:", "options": ["Consumers", "Producers", "Decomposers", "Predators"], "answer": 1, "explanation": "Producers (autotrophs), like green plants, make their own food using sunlight, CO\u2082 and water through photosynthesis."}, {"id": 22, "topic": "Ecology", "difficulty": "Easy", "question": "In a food chain: Grass \u2192 Grasshopper \u2192 Frog \u2192 Snake, the grasshopper is a:", "options": ["Producer", "Primary consumer", "Secondary consumer", "Decomposer"], "answer": 1, "explanation": "The grasshopper eats the producer (grass), making it a primary consumer (herbivore/first-order consumer)."}, {"id": 23, "topic": "Ecology", "difficulty": "Medium", "question": "The maximum number of organisms that an environment can support is called:", "options": ["Population density", "Carrying capacity", "Biotic potential", "Ecological niche"], "answer": 1, "explanation": "Carrying capacity (K) is the maximum population size of a species that an environment can sustain given available resources."}, {"id": 24, "topic": "Ecology", "difficulty": "Medium", "question": "Which of the following is a density-dependent factor affecting populations?", "options": ["Flood", "Earthquake", "Disease", "Volcanic eruption"], "answer": 2, "explanation": "Disease is density-dependent because it spreads more easily when population density is high. Floods, earthquakes, and volcanic eruptions are density-independent."}, {"id": 25, "topic": "Ecology", "difficulty": "Hard", "question": "In the nitrogen cycle, the conversion of nitrogen gas (N\u2082) to ammonia (NH\u2083) by bacteria is called:", "options": ["Nitrification", "Denitrification", "Nitrogen fixation", "Ammonification"], "answer": 2, "explanation": "Nitrogen fixation converts atmospheric N\u2082 into ammonia (NH\u2083). Nitrification converts ammonia to nitrates; denitrification converts nitrates back to N\u2082."}]};
window.SCIENCE_DATA["mathematics"] = {"subject": "Mathematics", "questions": [{"id": 1, "topic": "Logarithms", "difficulty": "Easy", "question": "The value of log\u2081\u2080 100 is:", "options": ["1", "2", "10", "100"], "answer": 1, "explanation": "log\u2081\u2080 100 = log\u2081\u2080 10\u00b2 = 2. The logarithm asks: 10 raised to what power gives 100? Answer: 2."}, {"id": 2, "topic": "Logarithms", "difficulty": "Easy", "question": "If log\u2081\u2080 x = 3, then x =:", "options": ["30", "300", "1000", "10000"], "answer": 2, "explanation": "log\u2081\u2080 x = 3 means x = 10\u00b3 = 1000."}, {"id": 3, "topic": "Logarithms", "difficulty": "Medium", "question": "The logarithm of 1 to any base is:", "options": ["0", "1", "Undefined", "The base itself"], "answer": 0, "explanation": "log_b 1 = 0 for any valid base b, because b\u2070 = 1."}, {"id": 4, "topic": "Logarithms", "difficulty": "Medium", "question": "log\u2082 64 + log\u2082 4 equals:", "options": ["8", "10", "6", "256"], "answer": 0, "explanation": "log\u2082 64 = 6 (2\u2076 = 64) and log\u2082 4 = 2 (2\u00b2 = 4). So 6 + 2 = 8."}, {"id": 5, "topic": "Logarithms", "difficulty": "Hard", "question": "Given that log\u2081\u2080 2 = 0.3010, find log\u2081\u2080 5.", "options": ["0.6990", "0.3010", "1.6990", "0.5000"], "answer": 0, "explanation": "log\u2081\u2080 5 = log\u2081\u2080(10/2) = log\u2081\u2080 10 - log\u2081\u2080 2 = 1 - 0.3010 = 0.6990."}, {"id": 6, "topic": "Sequences", "difficulty": "Easy", "question": "The next term in the sequence 2, 5, 8, 11, ... is:", "options": ["12", "13", "14", "15"], "answer": 2, "explanation": "This is an arithmetic sequence with common difference 3. 11 + 3 = 14."}, {"id": 7, "topic": "Sequences", "difficulty": "Easy", "question": "The 10th term of the arithmetic sequence 3, 7, 11, 15, ... is:", "options": ["39", "37", "43", "41"], "answer": 0, "explanation": "a = 3, d = 4. Tn = a + (n-1)d = 3 + (9)(4) = 3 + 36 = 39."}, {"id": 8, "topic": "Sequences", "difficulty": "Medium", "question": "The sum of the first 20 terms of the AP: 2, 5, 8, 11, ... is:", "options": ["610", "590", "630", "650"], "answer": 0, "explanation": "a = 2, d = 3, n = 20. T\u2082\u2080 = 2 + 19(3) = 59. S\u2082\u2080 = n(a + Tn)/2 = 20(2 + 59)/2 = 20 \u00d7 30.5 = 610."}, {"id": 9, "topic": "Sequences", "difficulty": "Medium", "question": "The geometric sequence 3, 6, 12, 24, ... has a common ratio of:", "options": ["2", "3", "4", "6"], "answer": 0, "explanation": "Common ratio r = Tn/T(n-1) = 6/3 = 12/6 = 2."}, {"id": 10, "topic": "Sequences", "difficulty": "Hard", "question": "The 7th term of the geometric progression 2, 6, 18, ... is:", "options": ["1458", "486", "4374", "729"], "answer": 0, "explanation": "a = 2, r = 3. T\u2087 = ar\u2076 = 2 \u00d7 3\u2076 = 2 \u00d7 729 = 1458."}, {"id": 11, "topic": "Trigonometry", "difficulty": "Easy", "question": "The value of sin 30\u00b0 is:", "options": ["1/2", "\u221a3/2", "1", "0"], "answer": 0, "explanation": "sin 30\u00b0 = 1/2 = 0.5. This is a standard trigonometric value."}, {"id": 12, "topic": "Trigonometry", "difficulty": "Easy", "question": "In a right-angled triangle, cos \u03b8 is equal to:", "options": ["Opposite/Hypotenuse", "Adjacent/Hypotenuse", "Opposite/Adjacent", "Hypotenuse/Adjacent"], "answer": 1, "explanation": "cos \u03b8 = Adjacent/Hypotenuse (CAH from SOH-CAH-TOA)."}, {"id": 13, "topic": "Trigonometry", "difficulty": "Medium", "question": "If tan \u03b8 = 1 and \u03b8 is acute, then \u03b8 =:", "options": ["30\u00b0", "45\u00b0", "60\u00b0", "90\u00b0"], "answer": 1, "explanation": "tan 45\u00b0 = 1, so \u03b8 = 45\u00b0."}, {"id": 14, "topic": "Trigonometry", "difficulty": "Medium", "question": "The value of cos 60\u00b0 is:", "options": ["\u221a3/2", "1/2", "\u221a2/2", "1"], "answer": 1, "explanation": "cos 60\u00b0 = 1/2 = 0.5. This is a standard trigonometric value."}, {"id": 15, "topic": "Trigonometry", "difficulty": "Hard", "question": "In triangle ABC, a = 5, b = 7, C = 60\u00b0. The area of the triangle is:", "options": ["15.31", "17.5", "35", "20"], "answer": 0, "explanation": "Area = \u00bdab sin C = \u00bd \u00d7 5 \u00d7 7 \u00d7 sin 60\u00b0 = 17.5 \u00d7 0.866 = 15.15 \u2248 15.31."}, {"id": 16, "topic": "Calculus Intro", "difficulty": "Easy", "question": "The derivative of x\u00b2 is:", "options": ["x", "2x", "2", "x\u00b2"], "answer": 1, "explanation": "Using the power rule: d/dx(x\u207f) = nx\u207f\u207b\u00b9. So d/dx(x\u00b2) = 2x\u00b9 = 2x."}, {"id": 17, "topic": "Calculus Intro", "difficulty": "Easy", "question": "The gradient (slope) of the curve y = 3x + 5 is:", "options": ["3", "5", "8", "3x"], "answer": 0, "explanation": "y = 3x + 5 is a straight line with gradient (slope) = 3. The derivative dy/dx = 3."}, {"id": 18, "topic": "Calculus Intro", "difficulty": "Medium", "question": "The integral of 2x with respect to x is:", "options": ["x\u00b2", "2x\u00b2", "2", "x\u00b2 + C"], "answer": 3, "explanation": "\u222b2x dx = x\u00b2 + C, where C is the constant of integration."}, {"id": 19, "topic": "Calculus Intro", "difficulty": "Medium", "question": "The derivative of 5x\u00b3 is:", "options": ["15x\u00b2", "5x\u00b2", "15x\u00b3", "3x\u00b2"], "answer": 0, "explanation": "d/dx(5x\u00b3) = 5 \u00d7 3x\u00b2 = 15x\u00b2."}, {"id": 20, "topic": "Calculus Intro", "difficulty": "Hard", "question": "The gradient of y = x\u00b2 at x = 3 is:", "options": ["6", "9", "3", "18"], "answer": 0, "explanation": "dy/dx = 2x. At x = 3, gradient = 2(3) = 6."}, {"id": 21, "topic": "Logarithms", "difficulty": "Medium", "question": "log\u2081\u2080 0.01 equals:", "options": ["-2", "2", "0.01", "-1"], "answer": 0, "explanation": "0.01 = 10\u207b\u00b2, so log\u2081\u2080 0.01 = -2."}, {"id": 22, "topic": "Sequences", "difficulty": "Medium", "question": "The nth term of the sequence 5, 8, 11, 14, ... is:", "options": ["3n + 2", "3n + 5", "2n + 3", "5n + 3"], "answer": 0, "explanation": "d = 3, a = 5. Tn = a + (n-1)d = 5 + (n-1)3 = 5 + 3n - 3 = 3n + 2."}, {"id": 23, "topic": "Trigonometry", "difficulty": "Medium", "question": "sin 90\u00b0 has the value:", "options": ["0", "1", "-1", "\u221a2/2"], "answer": 1, "explanation": "sin 90\u00b0 = 1. At 90\u00b0, the opposite side equals the hypotenuse in the unit circle."}, {"id": 24, "topic": "Calculus Intro", "difficulty": "Hard", "question": "If y = 4x\u00b2 - 2x, the value of dy/dx when x = 2 is:", "options": ["14", "12", "16", "10"], "answer": 0, "explanation": "dy/dx = 8x - 2. When x = 2: dy/dx = 8(2) - 2 = 16 - 2 = 14."}, {"id": 25, "topic": "Logarithms", "difficulty": "Hard", "question": "If log\u2081\u2080 3 = 0.477, then log\u2081\u2080 300 is:", "options": ["2.477", "1.477", "2.4770", "0.477"], "answer": 0, "explanation": "log\u2081\u2080 300 = log\u2081\u2080(3 \u00d7 100) = log\u2081\u2080 3 + log\u2081\u2080 100 = 0.477 + 2 = 2.477."}]};
window.SCIENCE_DATA["further-mathematics"] = {"subject": "Further Mathematics", "questions": [{"id": 1, "topic": "Vectors", "difficulty": "Easy", "question": "If a = (3, 4) and b = (1, 2), then a + b =:", "options": ["(4, 6)", "(2, 2)", "(3, 6)", "(4, 8)"], "answer": 0, "explanation": "Add corresponding components: (3+1, 4+2) = (4, 6)."}, {"id": 2, "topic": "Vectors", "difficulty": "Medium", "question": "The dot product of vectors a = (2, 3) and b = (4, 1) is:", "options": ["11", "14", "10", "8"], "answer": 0, "explanation": "a\u00b7b = (2)(4) + (3)(1) = 8 + 3 = 11."}, {"id": 3, "topic": "Vectors", "difficulty": "Medium", "question": "The magnitude of the vector (3, 4) is:", "options": ["5", "7", "12", "25"], "answer": 0, "explanation": "|v| = \u221a(3\u00b2 + 4\u00b2) = \u221a(9 + 16) = \u221a25 = 5."}, {"id": 4, "topic": "Matrices", "difficulty": "Easy", "question": "The order of the matrix [1 2 3; 4 5 6] is:", "options": ["2 \u00d7 3", "3 \u00d7 2", "2 \u00d7 2", "3 \u00d7 3"], "answer": 0, "explanation": "The matrix has 2 rows and 3 columns, so its order is 2 \u00d7 3."}, {"id": 5, "topic": "Matrices", "difficulty": "Medium", "question": "If A = [2 1; 3 4], the determinant of A is:", "options": ["5", "8", "14", "11"], "answer": 0, "explanation": "det(A) = (2)(4) - (1)(3) = 8 - 3 = 5."}, {"id": 6, "topic": "Matrices", "difficulty": "Medium", "question": "The identity matrix of order 2 \u00d7 2 is:", "options": ["[1 0; 0 1]", "[0 1; 1 0]", "[1 1; 1 1]", "[2 0; 0 2]"], "answer": 0, "explanation": "The identity matrix has 1s on the main diagonal and 0s elsewhere: [1 0; 0 1]."}, {"id": 7, "topic": "Matrices", "difficulty": "Hard", "question": "If A = [1 2; 3 4] and B = [2 0; 1 3], find AB.", "options": ["[4 6; 10 12]", "[4 10; 6 12]", "[2 6; 10 4]", "[6 4; 12 10]"], "answer": 0, "explanation": "AB = [1\u00d72+2\u00d71, 1\u00d70+2\u00d73; 3\u00d72+4\u00d71, 3\u00d70+4\u00d73] = [4, 6; 10, 12]."}, {"id": 8, "topic": "Differentiation", "difficulty": "Easy", "question": "Differentiate y = 3x\u2074 with respect to x.", "options": ["12x\u00b3", "3x\u00b3", "12x\u2074", "4x\u00b3"], "answer": 0, "explanation": "dy/dx = 3 \u00d7 4x\u00b3 = 12x\u00b3."}, {"id": 9, "topic": "Differentiation", "difficulty": "Medium", "question": "The gradient of y = x\u00b3 - 2x at x = 2 is:", "options": ["10", "8", "6", "4"], "answer": 0, "explanation": "dy/dx = 3x\u00b2 - 2. At x = 2: 3(4) - 2 = 12 - 2 = 10."}, {"id": 10, "topic": "Differentiation", "difficulty": "Hard", "question": "If y = (2x + 1)\u00b3, then dy/dx =:", "options": ["6(2x+1)\u00b2", "3(2x+1)\u00b2", "6(2x+1)\u00b3", "(2x+1)\u00b2"], "answer": 0, "explanation": "Using chain rule: dy/dx = 3(2x+1)\u00b2 \u00d7 2 = 6(2x+1)\u00b2."}, {"id": 11, "topic": "Integration", "difficulty": "Easy", "question": "\u222b3x\u00b2 dx =:", "options": ["x\u00b3 + C", "3x\u00b3 + C", "6x + C", "x\u00b3"], "answer": 0, "explanation": "\u222b3x\u00b2 dx = 3 \u00d7 x\u00b3/3 + C = x\u00b3 + C."}, {"id": 12, "topic": "Integration", "difficulty": "Medium", "question": "\u222b\u2080\u00b2 4x dx =:", "options": ["8", "16", "4", "12"], "answer": 0, "explanation": "\u222b4x dx = 2x\u00b2. Evaluating from 0 to 2: 2(4) - 2(0) = 8."}, {"id": 13, "topic": "Probability", "difficulty": "Easy", "question": "Two fair dice are thrown. The probability of getting a sum of 7 is:", "options": ["1/6", "1/9", "1/12", "5/36"], "answer": 0, "explanation": "Favourable outcomes: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6. Total outcomes = 36. P = 6/36 = 1/6."}, {"id": 14, "topic": "Probability", "difficulty": "Medium", "question": "A bag contains 3 red and 5 blue balls. Two balls are drawn without replacement. P(both red) =:", "options": ["3/28", "3/8", "9/64", "1/28"], "answer": 0, "explanation": "P(first red) = 3/8, P(second red) = 2/7. P(both) = 3/8 \u00d7 2/7 = 6/56 = 3/28."}, {"id": 15, "topic": "Probability", "difficulty": "Hard", "question": "Events A and B are independent. P(A) = 0.3 and P(B) = 0.5. P(A \u222a B) =:", "options": ["0.65", "0.15", "0.80", "0.45"], "answer": 0, "explanation": "P(A\u222aB) = P(A) + P(B) - P(A\u2229B). For independent events: P(A\u2229B) = 0.3 \u00d7 0.5 = 0.15. So P(A\u222aB) = 0.3 + 0.5 - 0.15 = 0.65."}, {"id": 16, "topic": "Statics", "difficulty": "Medium", "question": "The moment of a force of 10 N about a point 0.5 m from the line of action is:", "options": ["5 Nm", "20 Nm", "15 Nm", "50 Nm"], "answer": 0, "explanation": "Moment = Force \u00d7 perpendicular distance = 10 \u00d7 0.5 = 5 Nm."}, {"id": 17, "topic": "Dynamics", "difficulty": "Medium", "question": "A body of mass 5 kg has a momentum of 20 kg m/s. Its velocity is:", "options": ["4 m/s", "25 m/s", "15 m/s", "100 m/s"], "answer": 0, "explanation": "p = mv, so v = p/m = 20/5 = 4 m/s."}, {"id": 18, "topic": "Dynamics", "difficulty": "Hard", "question": "A force of 20 N acts on a body of mass 4 kg for 5 s. The impulse is:", "options": ["100 Ns", "20 Ns", "5 Ns", "400 Ns"], "answer": 0, "explanation": "Impulse = Force \u00d7 time = 20 \u00d7 5 = 100 Ns. (Also equals change in momentum.)"}, {"id": 19, "topic": "Vectors", "difficulty": "Hard", "question": "Two vectors a = (1, 2) and b = (k, 6) are parallel. The value of k is:", "options": ["3", "2", "6", "12"], "answer": 0, "explanation": "For parallel vectors: a\u2081/a\u2082 = b\u2081/b\u2082. So 1/2 = k/6, giving k = 3."}, {"id": 20, "topic": "Matrices", "difficulty": "Hard", "question": "The inverse of the matrix [3 1; 5 2] is:", "options": ["[2 -1; -5 3]", "[-2 1; 5 -3]", "[2 -5; -1 3]", "[3 -1; -5 2]"], "answer": 0, "explanation": "det = 6 - 5 = 1. A\u207b\u00b9 = (1/1)[2 -1; -5 3] = [2 -1; -5 3]."}, {"id": 21, "topic": "Differentiation", "difficulty": "Easy", "question": "The derivative of a constant function f(x) = 7 is:", "options": ["0", "7", "1", "Undefined"], "answer": 0, "explanation": "The derivative of any constant is 0, since the gradient of a horizontal line is 0."}, {"id": 22, "topic": "Integration", "difficulty": "Medium", "question": "\u222b(6x\u00b2 + 4x) dx =:", "options": ["2x\u00b3 + 2x\u00b2 + C", "6x\u00b3 + 4x\u00b2 + C", "3x\u00b3 + 2x\u00b2 + C", "2x\u00b3 + 4x + C"], "answer": 0, "explanation": "\u222b6x\u00b2 dx = 2x\u00b3 and \u222b4x dx = 2x\u00b2. So result = 2x\u00b3 + 2x\u00b2 + C."}, {"id": 23, "topic": "Probability", "difficulty": "Medium", "question": "The probability of not getting a head when a fair coin is tossed once is:", "options": ["0.5", "1", "0", "0.25"], "answer": 0, "explanation": "P(not head) = P(tail) = 0.5."}, {"id": 24, "topic": "Statics", "difficulty": "Hard", "question": "A uniform beam of weight 200 N is pivoted at its centre. A weight of 50 N hangs 2 m from the pivot. Where must a 100 N weight be hung to balance it?", "options": ["1 m from pivot", "2 m from pivot", "4 m from pivot", "0.5 m from pivot"], "answer": 0, "explanation": "For equilibrium: clockwise moment = anticlockwise moment. 100 \u00d7 d = 50 \u00d7 2, so d = 100/100 = 1 m from pivot on the other side."}, {"id": 25, "topic": "Dynamics", "difficulty": "Easy", "question": "According to Newton's second law, F = ma. A body of mass 3 kg accelerates at 4 m/s\u00b2. The force is:", "options": ["12 N", "7 N", "1.33 N", "36 N"], "answer": 0, "explanation": "F = ma = 3 \u00d7 4 = 12 N."}]};
window.SCIENCE_DATA["english"] = {"subject": "English", "questions": [{"id": 1, "topic": "Comprehension", "difficulty": "Easy", "question": "Choose the word nearest in meaning to 'abundant':", "options": ["Scarce", "Plentiful", "Rare", "Limited"], "answer": 1, "explanation": "Abundant means existing in large quantities; plentiful. Its opposite is scarce."}, {"id": 2, "topic": "Vocabulary", "difficulty": "Easy", "question": "Choose the word nearest in meaning to 'benevolent':", "options": ["Cruel", "Kind", "Selfish", "Hostile"], "answer": 1, "explanation": "Benevolent means well-meaning, kindly, charitable."}, {"id": 3, "topic": "Vocabulary", "difficulty": "Easy", "question": "Choose the opposite (antonym) of 'transparent':", "options": ["Clear", "Opaque", "Visible", "Bright"], "answer": 1, "explanation": "Transparent means see-through. Opaque means not able to be seen through \u2014 its direct opposite."}, {"id": 4, "topic": "Grammar", "difficulty": "Easy", "question": "Choose the correct sentence:", "options": ["He don't have a book", "He doesn't have a book", "He not have a book", "He haven't a book"], "answer": 1, "explanation": "The correct form for third person singular present tense is 'doesn't' (does not) followed by the base verb 'have'."}, {"id": 5, "topic": "Grammar", "difficulty": "Medium", "question": "Identify the correct passive form of: 'The boy ate the mango.'", "options": ["The mango was eaten by the boy", "The mango is eaten by the boy", "The mango ate the boy", "The mango has ate by the boy"], "answer": 0, "explanation": "The past tense 'ate' becomes 'was eaten' in passive voice. Object becomes subject: The mango was eaten by the boy."}, {"id": 6, "topic": "Grammar", "difficulty": "Medium", "question": "Choose the correctly punctuated sentence:", "options": ["Where are you going, John?", "Where are you going John?", "Where, are you going John?", "Where are you, going John?"], "answer": 0, "explanation": "Direct questions end with a question mark, and a name in direct address is set off by a comma."}, {"id": 7, "topic": "Grammar", "difficulty": "Medium", "question": "The plural of 'crisis' is:", "options": ["crisises", "crises", "crisis", "crisi"], "answer": 1, "explanation": "Crisis is from Greek; its plural is crises (change of -is to -es)."}, {"id": 8, "topic": "Comprehension", "difficulty": "Medium", "question": "'He kicked the bucket' is an example of:", "options": ["A literal statement", "An idiom", "A metaphor", "A simile"], "answer": 1, "explanation": "This is an idiom meaning 'he died'. It cannot be understood from the individual meanings of the words."}, {"id": 9, "topic": "Comprehension", "difficulty": "Medium", "question": "Which figure of speech is: 'She is as busy as a bee'?", "options": ["Metaphor", "Simile", "Personification", "Hyperbole"], "answer": 1, "explanation": "A simile compares two things using 'like' or 'as'. This compares her busyness to a bee's."}, {"id": 10, "topic": "Comprehension", "difficulty": "Hard", "question": "Which figure of speech is: 'The wind whispered through the trees'?", "options": ["Simile", "Hyperbole", "Personification", "Irony"], "answer": 2, "explanation": "Personification gives human qualities (whispering) to non-human things (wind)."}, {"id": 11, "topic": "Vocabulary", "difficulty": "Medium", "question": "Choose the word nearest in meaning to 'frugal':", "options": ["Wasteful", "Thrifty", "Generous", "Lavish"], "answer": 1, "explanation": "Frugal means careful with money, economical, thrifty."}, {"id": 12, "topic": "Grammar", "difficulty": "Medium", "question": "Choose the correct option: 'If I ______ a bird, I would fly south.'", "options": ["am", "was", "were", "will be"], "answer": 2, "explanation": "This is a second conditional sentence (unreal present). The subjunctive 'were' is used for all subjects."}, {"id": 13, "topic": "Grammar", "difficulty": "Easy", "question": "'The sun ______ in the east.' Choose the correct verb form:", "options": ["rise", "rises", "rose", "rising"], "answer": 1, "explanation": "This is a general truth/habitual action, so simple present tense is used. 'The sun' is third person singular, so 'rises'."}, {"id": 14, "topic": "Comprehension", "difficulty": "Medium", "question": "A synonym for 'diligent' is:", "options": ["Lazy", "Hardworking", "Careless", "Slow"], "answer": 1, "explanation": "Diligent means showing careful and persistent effort; hardworking."}, {"id": 15, "topic": "Vocabulary", "difficulty": "Hard", "question": "Choose the word nearest in meaning to 'obstinate':", "options": ["Obedient", "Stubborn", "Flexible", "Gentle"], "answer": 1, "explanation": "Obstinate means stubbornly refusing to change one's opinion; unyielding."}, {"id": 16, "topic": "Grammar", "difficulty": "Hard", "question": "Identify the correct reported speech: He said, 'I am going to school now.'", "options": ["He said that he is going to school now", "He said that he was going to school then", "He said that he went to school now", "He said that I was going to school"], "answer": 1, "explanation": "In reported speech: 'am going' \u2192 'was going', 'now' \u2192 'then', and first person 'I' \u2192 third person 'he'."}, {"id": 17, "topic": "Comprehension", "difficulty": "Easy", "question": "'His speech was a breath of fresh air' is:", "options": ["An idiom", "A proverb", "A tautology", "An oxymoron"], "answer": 0, "explanation": "'A breath of fresh air' is an idiom meaning something new and refreshing, different from what came before."}, {"id": 18, "topic": "Grammar", "difficulty": "Medium", "question": "Which sentence contains a relative pronoun?", "options": ["The book is interesting", "The book that I read was interesting", "I read the book", "Reading books is fun"], "answer": 1, "explanation": "'That' is a relative pronoun introducing the relative clause 'that I read'."}, {"id": 19, "topic": "Vocabulary", "difficulty": "Medium", "question": "The word 'meticulous' means:", "options": ["Careless", "Extremely careful about details", "Very quick", "Extremely tall"], "answer": 1, "explanation": "Meticulous means showing great attention to detail; very careful and precise."}, {"id": 20, "topic": "Comprehension", "difficulty": "Hard", "question": "Which sentence is a paradox?", "options": ["She is as tall as a building", "I must be cruel to be kind", "The classroom was as quiet as a graveyard", "He runs like the wind"], "answer": 1, "explanation": "A paradox is a statement that appears self-contradictory but may reveal a truth. 'Cruel to be kind' seems contradictory."}, {"id": 21, "topic": "Grammar", "difficulty": "Easy", "question": "Choose the correct sentence:", "options": ["Me and him went to school", "He and I went to school", "Him and me went to school", "I and he went to school"], "answer": 1, "explanation": "Subject pronouns (he, I) are used as subjects. Also, etiquette places 'I' last when referring to yourself with another person."}, {"id": 22, "topic": "Vocabulary", "difficulty": "Hard", "question": "A word that is spelled the same but has different meanings (e.g., 'bat') is called:", "options": ["Homophone", "Homonym", "Synonym", "Antonym"], "answer": 1, "explanation": "A homonym has the same spelling but different meanings (bat = animal, bat = sports equipment). Homophones sound the same but may be spelled differently."}, {"id": 23, "topic": "Comprehension", "difficulty": "Medium", "question": "'Many hands make light work' is best described as:", "options": ["An idiom", "A proverb", "A metaphor", "A euphemism"], "answer": 1, "explanation": "A proverb is a short saying expressing a general truth or piece of advice. This teaches that cooperation makes tasks easier."}, {"id": 24, "topic": "Grammar", "difficulty": "Hard", "question": "The passive voice of: 'The teacher will punish the students.'", "options": ["The students will be punished by the teacher", "The students were punished by the teacher", "The students are punished by the teacher", "The students would punish the teacher"], "answer": 0, "explanation": "Future tense 'will punish' becomes 'will be punished' in passive voice."}, {"id": 25, "topic": "Vocabulary", "difficulty": "Medium", "question": "The antonym of 'benevolent' is:", "options": ["Generous", "Malevolent", "Friendly", "Compassionate"], "answer": 1, "explanation": "Malevolent means wishing harm to others \u2014 the direct opposite of benevolent (wishing good for others)."}]};
window.SCIENCE_DATA["computer-science"] = {"subject": "Computer Science", "questions": [{"id": 1, "topic": "Computer Basics", "difficulty": "Easy", "question": "The full meaning of CPU is:", "options": ["Central Processing Unit", "Computer Personal Unit", "Central Program Utility", "Core Processing Unit"], "answer": 0, "explanation": "CPU stands for Central Processing Unit. It is the primary component that executes instructions and processes data in a computer."}, {"id": 2, "topic": "Computer Basics", "difficulty": "Easy", "question": "Which of the following is an input device?", "options": ["Monitor", "Printer", "Keyboard", "Speaker"], "answer": 2, "explanation": "A keyboard is an input device used to enter data. Monitor, printer and speaker are output devices."}, {"id": 3, "topic": "Computer Basics", "difficulty": "Easy", "question": "1 kilobyte (KB) is equal to:", "options": ["1000 bytes", "1024 bytes", "1024 bits", "100 bytes"], "answer": 1, "explanation": "1 KB = 1024 bytes. (In binary computation, 1 KB = 2\u00b9\u2070 bytes = 1024 bytes.)"}, {"id": 4, "topic": "Computer Basics", "difficulty": "Medium", "question": "The brain of the computer is the:", "options": ["RAM", "Hard disk", "CPU", "Motherboard"], "answer": 2, "explanation": "The CPU (Central Processing Unit) is called the brain of the computer because it performs all processing and calculation."}, {"id": 5, "topic": "Programming", "difficulty": "Easy", "question": "Which of the following is a programming language?", "options": ["Windows", "Python", "Chrome", "MS Word"], "answer": 1, "explanation": "Python is a programming language. Windows and Chrome are software applications; MS Word is a word processor."}, {"id": 6, "topic": "Programming", "difficulty": "Medium", "question": "In programming, a 'variable' is:", "options": ["A fixed value that cannot change", "A named storage location for data that can change", "A type of loop", "A programming error"], "answer": 1, "explanation": "A variable is a named container in memory that stores a value which can be changed (modified) during program execution."}, {"id": 7, "topic": "Programming", "difficulty": "Medium", "question": "A 'bug' in a program is:", "options": ["A feature", "An error or fault", "A type of loop", "A variable name"], "answer": 1, "explanation": "A bug is an error, flaw, or fault in a program that produces incorrect or unexpected results."}, {"id": 8, "topic": "Programming", "difficulty": "Medium", "question": "The correct order of steps in programming is:", "options": ["Code \u2192 Test \u2192 Problem \u2192 Design", "Problem \u2192 Design \u2192 Code \u2192 Test", "Test \u2192 Code \u2192 Design \u2192 Problem", "Design \u2192 Problem \u2192 Test \u2192 Code"], "answer": 1, "explanation": "The standard programming process: 1) Define the problem, 2) Design the solution (algorithm), 3) Write the code, 4) Test and debug."}, {"id": 9, "topic": "Programming", "difficulty": "Hard", "question": "Which control structure repeats a block of code as long as a condition is true?", "options": ["Sequence", "Selection", "Iteration (Loop)", "Function"], "answer": 2, "explanation": "Iteration (looping) repeats a block of code. Examples include for loops and while loops."}, {"id": 10, "topic": "Networking", "difficulty": "Easy", "question": "LAN stands for:", "options": ["Large Area Network", "Local Area Network", "Long Access Network", "Linked Area Network"], "answer": 1, "explanation": "LAN = Local Area Network. It connects computers within a limited area like a school or office."}, {"id": 11, "topic": "Networking", "difficulty": "Easy", "question": "The full meaning of the Internet is:", "options": ["International Network", "Interconnected Network of Networks", "Internal Network", "Information Network"], "answer": 1, "explanation": "The Internet is a global system of interconnected computer networks that communicate using standard protocols."}, {"id": 12, "topic": "Networking", "difficulty": "Medium", "question": "Which device is used to connect two or more networks together?", "options": ["Hub", "Switch", "Router", "Modem"], "answer": 2, "explanation": "A router directs data between different networks. A hub/switch connects devices within the same network."}, {"id": 13, "topic": "Data Representation", "difficulty": "Medium", "question": "The binary number 1010 is equal to which decimal number?", "options": ["8", "10", "12", "14"], "answer": 1, "explanation": "1010 in binary = 1\u00d78 + 0\u00d74 + 1\u00d72 + 0\u00d71 = 8 + 0 + 2 + 0 = 10 in decimal."}, {"id": 14, "topic": "Data Representation", "difficulty": "Medium", "question": "The hexadecimal equivalent of the decimal number 15 is:", "options": ["F", "E", "D", "1111"], "answer": 0, "explanation": "In hexadecimal (base 16): 10=A, 11=B, 12=C, 13=D, 14=E, 15=F. So 15 = F."}, {"id": 15, "topic": "Data Representation", "difficulty": "Hard", "question": "How many bits are in one byte?", "options": ["4", "8", "16", "32"], "answer": 1, "explanation": "One byte = 8 bits. A bit is the smallest unit of data (0 or 1)."}, {"id": 16, "topic": "Computer Basics", "difficulty": "Medium", "question": "Which type of software directly controls hardware?", "options": ["Application software", "System software (Operating System)", "Word processor", "Web browser"], "answer": 1, "explanation": "System software (specifically the Operating System) manages hardware resources and provides a platform for application software."}, {"id": 17, "topic": "Computer Basics", "difficulty": "Easy", "question": "RAM stands for:", "options": ["Random Access Memory", "Read Access Memory", "Rapid Access Memory", "Random Available Memory"], "answer": 0, "explanation": "RAM = Random Access Memory. It is volatile memory that temporarily stores data the CPU is currently using."}, {"id": 18, "topic": "Computer Basics", "difficulty": "Medium", "question": "Which of the following is a storage device?", "options": ["RAM", "ROM", "Hard disk", "CPU"], "answer": 2, "explanation": "A hard disk is a permanent (non-volatile) storage device. RAM and ROM are memory, not storage. CPU is a processor."}, {"id": 19, "topic": "Programming", "difficulty": "Hard", "question": "What is the output of this pseudocode: SET x = 5, SET y = 3, DISPLAY x + y?", "options": ["53", "8", "5", "3"], "answer": 1, "explanation": "The + operator adds the two numbers: 5 + 3 = 8. (If they were strings, it would concatenate to '53'.)"}, {"id": 20, "topic": "Networking", "difficulty": "Hard", "question": "The protocol used for sending emails is:", "options": ["HTTP", "FTP", "SMTP", "TCP/IP"], "answer": 2, "explanation": "SMTP (Simple Mail Transfer Protocol) is used for sending emails. HTTP is for web, FTP for file transfer, TCP/IP is a communication protocol suite."}, {"id": 21, "topic": "Computer Basics", "difficulty": "Easy", "question": "Which of these is an operating system?", "options": ["Microsoft Word", "Linux", "Google Chrome", "Adobe Photoshop"], "answer": 1, "explanation": "Linux is an operating system. Others are application programs."}, {"id": 22, "topic": "Programming", "difficulty": "Easy", "question": "An algorithm is:", "options": ["A type of computer", "A step-by-step procedure for solving a problem", "A programming language", "A hardware device"], "answer": 1, "explanation": "An algorithm is a finite sequence of well-defined instructions to solve a problem or perform a task."}, {"id": 23, "topic": "Data Representation", "difficulty": "Easy", "question": "The binary digits are:", "options": ["0 and 1", "1 and 2", "A and B", "0 and 9"], "answer": 0, "explanation": "Binary (base 2) uses only two digits: 0 and 1. Computers represent all data using these two binary digits."}, {"id": 24, "topic": "Computer Basics", "difficulty": "Medium", "question": "The permanent memory in a computer that cannot be erased is:", "options": ["RAM", "ROM", "Hard disk cache", "Virtual memory"], "answer": 1, "explanation": "ROM (Read-Only Memory) is non-volatile \u2014 it retains data even when power is off and is difficult to modify."}, {"id": 25, "topic": "Networking", "difficulty": "Medium", "question": "WWW stands for:", "options": ["World Wide Web", "Wide World Web", "Web World Wide", "World Web Wide"], "answer": 0, "explanation": "WWW = World Wide Web. It is an information system where documents and resources are identified by URLs and interlinked by hypertext."}]};
window.SCIENCE_DATA["geography"] = {"subject": "Geography", "questions": [{"id": 1, "topic": "Map Reading", "difficulty": "Easy", "question": "The imaginary line dividing the Earth into Northern and Southern Hemispheres is the:", "options": ["Prime Meridian", "Equator", "Tropic of Cancer", "International Date Line"], "answer": 1, "explanation": "The Equator (0\u00b0 latitude) divides Earth into Northern and Southern Hemispheres."}, {"id": 2, "topic": "Map Reading", "difficulty": "Easy", "question": "A scale of 1:50,000 means:", "options": ["1 cm on the map represents 50,000 cm on the ground", "1 cm on the map represents 50,000 km on the ground", "50,000 cm on the map represents 1 cm on the ground", "1 m on the map represents 50,000 m on the ground"], "answer": 0, "explanation": "A representative fraction scale of 1:50,000 means 1 unit on the map equals 50,000 of the same units on the ground (1 cm = 500 m)."}, {"id": 3, "topic": "Map Reading", "difficulty": "Medium", "question": "Lines of longitude are also called:", "options": ["Parallels", "Meridians", "Tropics", "Great circles"], "answer": 1, "explanation": "Lines of longitude are called meridians. The Prime Meridian (0\u00b0) passes through Greenwich, London."}, {"id": 4, "topic": "Physical Geography", "difficulty": "Easy", "question": "The layer of the Earth on which we live is the:", "options": ["Core", "Mantle", "Crust", "Asthenosphere"], "answer": 2, "explanation": "The crust is the outermost, thinnest layer of the Earth. It is the layer on which we live."}, {"id": 5, "topic": "Physical Geography", "difficulty": "Easy", "question": "The most abundant gas in the Earth's atmosphere is:", "options": ["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"], "answer": 2, "explanation": "Nitrogen makes up about 78% of the atmosphere, followed by oxygen at about 21%."}, {"id": 6, "topic": "Physical Geography", "difficulty": "Medium", "question": "The process by which rocks are broken down by water is called:", "options": ["Erosion", "Weathering", "Deposition", "Transportation"], "answer": 1, "explanation": "Weathering is the in-situ breakdown of rocks by physical, chemical, or biological agents. Erosion involves transport of weathered material."}, {"id": 7, "topic": "Physical Geography", "difficulty": "Medium", "question": "Which rock type is formed from cooled magma?", "options": ["Sedimentary", "Metamorphic", "Igneous", "Organic"], "answer": 2, "explanation": "Igneous rocks form when magma (intrusive) or lava (extrusive) cools and solidifies."}, {"id": 8, "topic": "Physical Geography", "difficulty": "Medium", "question": "The longest river in Africa is the:", "options": ["River Niger", "River Congo", "River Nile", "River Zambezi"], "answer": 2, "explanation": "The River Nile is the longest river in Africa (and was long considered the longest in the world) at about 6,650 km."}, {"id": 9, "topic": "Physical Geography", "difficulty": "Hard", "question": "The type of rainfall common in Lagos, Nigeria is:", "options": ["Relief (orographic)", "Convectional", "Frontal", "Cyclonic"], "answer": 1, "explanation": "Lagos experiences convectional rainfall: intense heating causes air to rise, cool, and form cumulonimbus clouds with heavy rain."}, {"id": 10, "topic": "Human Geography", "difficulty": "Easy", "question": "Nigeria has how many states?", "options": ["24", "30", "36", "40"], "answer": 2, "explanation": "Nigeria has 36 states plus the Federal Capital Territory (Abuja), making 37 administrative units."}, {"id": 11, "topic": "Human Geography", "difficulty": "Easy", "question": "The most populous city in Nigeria is:", "options": ["Abuja", "Kano", "Lagos", "Ibadan"], "answer": 2, "explanation": "Lagos is the most populous city in Nigeria and one of the largest cities in Africa, with over 15 million people."}, {"id": 12, "topic": "Human Geography", "difficulty": "Medium", "question": "The main occupational activity in the savanna regions of Nigeria is:", "options": ["Fishing", "Crop farming and livestock rearing", "Manufacturing", "Mining"], "answer": 1, "explanation": "The savanna supports both crop farming (millet, sorghum, yam) and livestock rearing (cattle, goats, sheep)."}, {"id": 13, "topic": "Human Geography", "difficulty": "Medium", "question": "A population pyramid that is wide at the base indicates:", "options": ["An aging population with high death rate", "A young population with high birth rate", "A declining population", "Equal numbers at all ages"], "answer": 1, "explanation": "A wide base means many young people (0-15 years), indicating a high birth rate \u2014 typical of developing countries like Nigeria."}, {"id": 14, "topic": "Climatology", "difficulty": "Medium", "question": "The instrument used to measure rainfall is:", "options": ["Barometer", "Thermometer", "Rain gauge", "Anemometer"], "answer": 2, "explanation": "A rain gauge measures the amount of rainfall. Barometer measures pressure, thermometer measures temperature, anemometer measures wind speed."}, {"id": 15, "topic": "Climatology", "difficulty": "Medium", "question": "The climate type found in the northern part of Nigeria is:", "options": ["Equatorial climate", "Tropical savanna climate", "Tropical monsoon climate", "Mediterranean climate"], "answer": 1, "explanation": "Northern Nigeria has a tropical savanna climate with distinct wet and dry seasons and less rainfall than the south."}, {"id": 16, "topic": "Map Reading", "difficulty": "Hard", "question": "On a map with a scale of 1:100,000, two places are 5 cm apart. The actual distance between them is:", "options": ["500 m", "5 km", "50 km", "500 km"], "answer": 1, "explanation": "Actual distance = 5 cm \u00d7 100,000 = 500,000 cm = 5,000 m = 5 km."}, {"id": 17, "topic": "Physical Geography", "difficulty": "Hard", "question": "Which of the following is a depositional landform?", "options": ["Waterfall", "Flood plain", "Gorge", "V-shaped valley"], "answer": 1, "explanation": "A flood plain is formed by deposition of sediment during river flooding. Waterfalls, gorges and V-shaped valleys are erosional landforms."}, {"id": 18, "topic": "Human Geography", "difficulty": "Easy", "question": "Crude oil is found mainly in which region of Nigeria?", "options": ["Northern region", "Middle Belt", "Niger Delta region", "South-East"], "answer": 2, "explanation": "The Niger Delta region (South-South) is the main oil-producing area of Nigeria."}, {"id": 19, "topic": "Physical Geography", "difficulty": "Easy", "question": "The imaginary line at 0\u00b0 longitude is called the:", "options": ["Equator", "Prime Meridian", "Tropic of Capricorn", "Arctic Circle"], "answer": 1, "explanation": "The Prime Meridian (0\u00b0 longitude) passes through Greenwich, London, and divides Earth into Eastern and Western Hemispheres."}, {"id": 20, "topic": "Climatology", "difficulty": "Hard", "question": "The instrument used to measure atmospheric pressure is:", "options": ["Hygrometer", "Barometer", "Wind vane", "Sun thermometer"], "answer": 1, "explanation": "A barometer measures atmospheric pressure. A hygrometer measures humidity, a wind vane shows wind direction."}, {"id": 21, "topic": "Map Reading", "difficulty": "Medium", "question": "Contour lines on a map join places of equal:", "options": ["Longitude", "Latitude", "Altitude (height)", "Temperature"], "answer": 2, "explanation": "Contour lines connect points of equal elevation/height above sea level. Closely spaced contours indicate steep slopes."}, {"id": 22, "topic": "Human Geography", "difficulty": "Medium", "question": "The major occupational activity in coastal areas of Nigeria is:", "options": ["Farming", "Fishing", "Cattle rearing", "Mining"], "answer": 1, "explanation": "Coastal communities engage mainly in fishing due to access to the Atlantic Ocean and abundant water bodies."}, {"id": 23, "topic": "Physical Geography", "difficulty": "Medium", "question": "The process of water changing to water vapour is called:", "options": ["Condensation", "Evaporation", "Precipitation", "Transpiration"], "answer": 1, "explanation": "Evaporation is the change of liquid water to gas (vapour) due to heat from the sun."}, {"id": 24, "topic": "Physical Geography", "difficulty": "Hard", "question": "The Earth's atmosphere layer where weather occurs is the:", "options": ["Stratosphere", "Troposphere", "Mesosphere", "Thermosphere"], "answer": 1, "explanation": "The troposphere (lowest layer, 0-12 km) contains most of the atmosphere's water vapour and is where all weather phenomena occur."}, {"id": 25, "topic": "Human Geography", "difficulty": "Hard", "question": "The Hausa people of Nigeria are mainly found in the:", "options": ["South-West", "South-East", "North", "Middle Belt"], "answer": 2, "explanation": "The Hausa (and Hausa-Fulani) people predominantly inhabit northern Nigeria, particularly states like Kano, Kaduna, and Sokoto."}]};
window.SCIENCE_DATA["civic-education"] = {"subject": "Civic Education", "questions": [{"id": 1, "topic": "Democracy", "difficulty": "Easy", "question": "The meaning of democracy is:", "options": ["Government by the military", "Government of the people, by the people, for the people", "Government by a single ruler", "Government by the rich"], "answer": 1, "explanation": "Democracy is a system of government where power rests with the people, exercised either directly or through elected representatives."}, {"id": 2, "topic": "Democracy", "difficulty": "Easy", "question": "In a democracy, sovereignty resides with:", "options": ["The president", "The military", "The citizens", "The judiciary"], "answer": 2, "explanation": "Popular sovereignty means the ultimate authority and power belongs to the citizens/people of the nation."}, {"id": 3, "topic": "Democracy", "difficulty": "Medium", "question": "The key feature of a federal system of government is:", "options": ["Centralization of power", "Division of power between central and regional governments", "Rule by one person", "Military control of government"], "answer": 1, "explanation": "Federalism divides power between a central (federal) government and regional (state) governments, each with constitutionally guaranteed powers."}, {"id": 4, "topic": "Human Rights", "difficulty": "Easy", "question": "Which of the following is a fundamental human right?", "options": ["Right to drive a car", "Right to life", "Right to free electricity", "Right to a private jet"], "answer": 1, "explanation": "The right to life is a fundamental human right recognized by the UN Universal Declaration of Human Rights and the Nigerian Constitution."}, {"id": 5, "topic": "Human Rights", "difficulty": "Easy", "question": "The right to vote and be voted for is called:", "options": ["Civil right", "Political right", "Economic right", "Social right"], "answer": 1, "explanation": "Political rights include the right to participate in government through voting, standing for election, and forming political parties."}, {"id": 6, "topic": "Human Rights", "difficulty": "Medium", "question": "Which document internationally guarantees human rights?", "options": ["The UN Charter of Human Rights", "The Atlantic Charter", "The Paris Accord", "The Geneva Budget"], "answer": 0, "explanation": "The Universal Declaration of Human Rights (UDHR), adopted by the UN in 1948, sets out fundamental human rights for all people."}, {"id": 7, "topic": "Human Rights", "difficulty": "Medium", "question": "A fundamental human right comes with:", "options": ["No responsibilities", "Corresponding duties and responsibilities", "Only financial benefits", "Military obligations"], "answer": 1, "explanation": "Rights and responsibilities are inseparable. Enjoying rights requires respecting the rights of others and fulfilling civic duties."}, {"id": 8, "topic": "Nigerian Government", "difficulty": "Easy", "question": "The three arms of government in Nigeria are:", "options": ["Army, Navy, Air Force", "Executive, Legislature, Judiciary", "President, Governor, Chairman", "Senate, House, Assembly"], "answer": 1, "explanation": "The three arms are the Executive (implements laws), Legislature (makes laws), and Judiciary (interprets laws). This ensures separation of powers."}, {"id": 9, "topic": "Nigerian Government", "difficulty": "Easy", "question": "The head of the Nigerian government is the:", "options": ["Senate President", "Chief Justice", "President", "Speaker"], "answer": 2, "explanation": "The President is both the Head of State and Head of Government in Nigeria's presidential system."}, {"id": 10, "topic": "Nigerian Government", "difficulty": "Medium", "question": "The Nigerian Constitution was last adopted in:", "options": ["1960", "1979", "1999", "2010"], "answer": 2, "explanation": "The 1999 Constitution of the Federal Republic of Nigeria (as amended) is the current constitution, adopted on 5 May 1999."}, {"id": 11, "topic": "Nigerian Government", "difficulty": "Medium", "question": "Nigeria's system of government is:", "options": ["Parliamentary", "Presidential", "Monarchical", "Confederal"], "answer": 1, "explanation": "Nigeria practices a presidential system where the President is both Head of State and Head of Government, elected separately from the legislature."}, {"id": 12, "topic": "Nigerian Government", "difficulty": "Medium", "question": "How many senators does Nigeria have at the National Assembly?", "options": ["240", "300", "360", "109"], "answer": 3, "explanation": "The Nigerian Senate has 109 members: 3 from each of the 36 states plus 1 from the FCT."}, {"id": 13, "topic": "Citizenship", "difficulty": "Easy", "question": "A citizen is a person who:", "options": ["Is visiting a country", "Has legal membership and full rights in a country", "Lives in a country temporarily", "Works in a country"], "answer": 1, "explanation": "A citizen is a legal member of a country with full rights and responsibilities, as recognized by the country's constitution."}, {"id": 14, "topic": "Citizenship", "difficulty": "Medium", "question": "Which of these is a civic responsibility?", "options": ["Paying taxes", "Owning a car", "Living in a big house", "Having a phone"], "answer": 0, "explanation": "Paying taxes is a civic duty. Tax revenue funds public services like roads, schools, hospitals, and security."}, {"id": 15, "topic": "Citizenship", "difficulty": "Medium", "question": "A good citizen should:", "options": ["Ignore elections", "Participate in community development", "Refuse to pay taxes", "Cause social unrest"], "answer": 1, "explanation": "Good citizens actively participate in their community \u2014 voting, obeying laws, paying taxes, and contributing to development."}, {"id": 16, "topic": "Rule of Law", "difficulty": "Easy", "question": "The 'rule of law' means:", "options": ["The president makes all laws", "Everyone is subject to and protected by the law", "Only the rich obey the law", "The military controls the law"], "answer": 1, "explanation": "The rule of law means all persons, institutions, and entities are accountable to laws that are publicly promulgated, equally enforced, and independently adjudicated."}, {"id": 17, "topic": "Rule of Law", "difficulty": "Medium", "question": "The principle of separation of powers ensures:", "options": ["One person rules the country", "Checks and balances among the three arms of government", "All government work is done by the military", "Laws are made by the courts"], "answer": 1, "explanation": "Separation of powers divides government into three arms with distinct functions, providing checks and balances to prevent abuse of power."}, {"id": 18, "topic": "Rule of Law", "difficulty": "Hard", "question": "Under the rule of law, no one is above the law. This means:", "options": ["Only ordinary citizens obey the law", "Even the President and government officials must obey the law", "Military personnel are exempt from the law", "The law only applies during elections"], "answer": 1, "explanation": "A fundamental aspect of the rule of law is that all people, including leaders and government officials, are equally subject to the law."}, {"id": 19, "topic": "Nigerian Government", "difficulty": "Hard", "question": "The Nigerian National Assembly consists of:", "options": ["Only the Senate", "The Senate and House of Representatives", "The House of Assembly and Senate", "The Executive and Legislature"], "answer": 1, "explanation": "The National Assembly has two chambers: the Senate (109 members) and the House of Representatives (360 members)."}, {"id": 20, "topic": "Patriotism", "difficulty": "Easy", "question": "Patriotism means:", "options": ["Loving one's country and being willing to defend it", "Loving only oneself", "Hating other countries", "Living abroad permanently"], "answer": 0, "explanation": "Patriotism is love for and devotion to one's country, including willingness to defend and develop it."}, {"id": 21, "topic": "Patriotism", "difficulty": "Medium", "question": "Which of these is an act of patriotism?", "options": ["Littering the environment", "Paying taxes honestly", "Avoiding national service", "Speaking against the country at every opportunity"], "answer": 1, "explanation": "Paying taxes honestly supports national development. Other options are unpatriotic acts."}, {"id": 22, "topic": "Human Rights", "difficulty": "Hard", "question": "Which of the following can limit a person's rights?", "options": ["The person's wealth", "Rights of other citizens and national security", "The person's education", "The person's age"], "answer": 1, "explanation": "Rights can be limited when their exercise violates the rights of others or threatens national security and public order."}, {"id": 23, "topic": "Democracy", "difficulty": "Medium", "question": "Free and fair elections are essential to democracy because they:", "options": ["Make politicians rich", "Allow citizens to choose their leaders", "Increase population", "Reduce the cost of government"], "answer": 1, "explanation": "Free and fair elections are the mechanism through which citizens choose their representatives, ensuring government accountability."}, {"id": 24, "topic": "Citizenship", "difficulty": "Hard", "question": "In Nigeria, a citizen by birth is one who:", "options": ["Was born in any country", "Was born in Nigeria to Nigerian parents, or born abroad to at least one Nigerian parent", "Has lived in Nigeria for 5 years", "Has a Nigerian passport"], "answer": 1, "explanation": "Section 25 of the Nigerian Constitution defines citizenship by birth as being born in Nigeria with at least one Nigerian parent, or born abroad to Nigerian parents."}, {"id": 25, "topic": "Rule of Law", "difficulty": "Medium", "question": "The judiciary in Nigeria is headed by the:", "options": ["President", "Senate President", "Chief Justice of Nigeria", "Attorney General"], "answer": 2, "explanation": "The Chief Justice of Nigeria (CJN) heads the judiciary and is the highest judicial officer in the country."}]};
window.SCIENCE_DATA["flashcards"] = {"cards": [{"id": 1, "subject": "Physics", "front": "Newton's Second Law of Motion", "back": "F = ma \u2014 Force equals mass times acceleration. The acceleration of a body is directly proportional to the force applied and inversely proportional to its mass."}, {"id": 2, "subject": "Physics", "front": "Equation of Motion (v = u + at)", "back": "Final velocity = initial velocity + acceleration \u00d7 time. Used when acceleration is constant."}, {"id": 3, "subject": "Physics", "front": "s = ut + \u00bdat\u00b2", "back": "Distance = (initial velocity \u00d7 time) + \u00bd \u00d7 acceleration \u00d7 time\u00b2. This is the second equation of motion."}, {"id": 4, "subject": "Physics", "front": "v\u00b2 = u\u00b2 + 2as", "back": "v\u00b2 = u\u00b2 + 2as. Third equation of motion relating velocities, acceleration, and distance. Doesn't require time."}, {"id": 5, "subject": "Physics", "front": "Refractive Index formula", "back": "n = c/v = 1/sin C = sin i / sin r. Where c = speed of light in vacuum, v = speed in medium, C = critical angle, i = angle of incidence, r = angle of refraction."}, {"id": 6, "subject": "Physics", "front": "Wave equation", "back": "v = f\u03bb \u2014 Wave speed equals frequency \u00d7 wavelength. Units: v (m/s), f (Hz), \u03bb (m)."}, {"id": 7, "subject": "Chemistry", "front": "Ideal Gas Equation", "back": "PV = nRT \u2014 Pressure \u00d7 Volume = moles \u00d7 gas constant \u00d7 temperature. R = 8.31 J/(mol\u00b7K) or 0.082 L\u00b7atm/(mol\u00b7K)."}, {"id": 8, "subject": "Chemistry", "front": "pH formula", "back": "pH = -log[H\u207a] \u2014 pH measures acidity. pH < 7 is acidic, pH = 7 is neutral, pH > 7 is alkaline (basic)."}, {"id": 9, "subject": "Chemistry", "front": "Mole formula", "back": "n = m/M \u2014 Number of moles = mass (g) / molar mass (g/mol). Also n = N/N\u2090 where N = number of particles, N\u2090 = 6.02 \u00d7 10\u00b2\u00b3."}, {"id": 10, "subject": "Chemistry", "front": "Molar Volume at STP", "back": "1 mole of any gas at STP occupies 22.4 litres. STP = Standard Temperature and Pressure (0\u00b0C, 1 atm)."}, {"id": 11, "subject": "Chemistry", "front": "Concentration formula", "back": "C = n/V \u2014 Concentration (mol/L) = moles of solute / volume of solution (L). Also expressed as c(mol/dm\u00b3)."}, {"id": 12, "subject": "Biology", "front": "Photosynthesis equation", "back": "6CO\u2082 + 6H\u2082O \u2192(light, chlorophyll)\u2192 C\u2086H\u2081\u2082O\u2086 + 6O\u2082. Raw materials: CO\u2082 and water. Products: glucose and oxygen. Occurs in chloroplasts."}, {"id": 13, "subject": "Biology", "front": "Aerobic Respiration equation", "back": "C\u2086H\u2081\u2082O\u2086 + 6O\u2082 \u2192 6CO\u2082 + 6H\u2082O + energy (ATP). Occurs in mitochondria. Produces about 38 ATP molecules per glucose."}, {"id": 14, "subject": "Biology", "front": "Parts of a plant cell", "back": "Cell wall, cell membrane, nucleus, cytoplasm, chloroplasts, vacuole (large central), mitochondria, ribosomes, endoplasmic reticulum, Golgi apparatus."}, {"id": 15, "subject": "Biology", "front": "Functions of the liver", "back": "1) Detoxification of poisons, 2) Production of bile, 3) Storage of glycogen, 4) Breakdown of red blood cells, 5) Metabolism of proteins and fats."}, {"id": 16, "subject": "Biology", "front": "Levels of organisation in biology", "back": "Cell \u2192 Tissue \u2192 Organ \u2192 Organ System \u2192 Organism \u2192 Population \u2192 Community \u2192 Ecosystem \u2192 Biome."}, {"id": 17, "subject": "Mathematics", "front": "Logarithm: log_b(x) = y means", "back": "b^y = x. The logarithm tells you what power the base must be raised to, to get x. Example: log\u2082(8) = 3 because 2\u00b3 = 8."}, {"id": 18, "subject": "Mathematics", "front": "Quadratic Formula", "back": "x = (-b \u00b1 \u221a(b\u00b2 - 4ac)) / 2a. For ax\u00b2 + bx + c = 0. The discriminant b\u00b2 - 4ac determines the nature of roots."}, {"id": 19, "subject": "Mathematics", "front": "Sum of an Arithmetic Progression (AP)", "back": "S\u2099 = n/2 \u00d7 [2a + (n-1)d] or S\u2099 = n/2 \u00d7 (a + l), where a = first term, d = common difference, l = last term, n = number of terms."}, {"id": 20, "subject": "Mathematics", "front": "Trigonometric ratios (SOH CAH TOA)", "back": "sin \u03b8 = Opposite/Hypotenuse, cos \u03b8 = Adjacent/Hypotenuse, tan \u03b8 = Opposite/Adjacent. Remember: SOH-CAH-TOA."}, {"id": 21, "subject": "Mathematics", "front": "Derivative power rule", "back": "d/dx(x\u207f) = nx\u207f\u207b\u00b9. The derivative of x raised to power n is n times x raised to power (n-1)."}, {"id": 22, "subject": "Further Maths", "front": "Dot product of vectors", "back": "a\u00b7b = |a||b|cos \u03b8. If a = (x\u2081,y\u2081) and b = (x\u2082,y\u2082), then a\u00b7b = x\u2081x\u2082 + y\u2081y\u2082. The result is a scalar."}, {"id": 23, "subject": "Further Maths", "front": "Determinant of 2\u00d72 matrix", "back": "For A = [a b; c d], det(A) = ad - bc. If det = 0, the matrix has no inverse (singular matrix)."}, {"id": 24, "subject": "Further Maths", "front": "Impulse-Momentum theorem", "back": "Impulse = Force \u00d7 time = Change in momentum = mv - mu. Units: Ns or kg\u00b7m/s."}, {"id": 25, "subject": "Computer Science", "front": "Binary to Decimal conversion", "back": "Multiply each bit by its place value (powers of 2) and add. E.g., 1011 = 1\u00d78 + 0\u00d74 + 1\u00d72 + 1\u00d71 = 11."}, {"id": 26, "subject": "Physics", "front": "Ohm's Law", "back": "V = IR \u2014 Voltage equals current \u00d7 resistance. V (volts), I (amperes), R (ohms)."}, {"id": 27, "subject": "Physics", "front": "Hooke's Law", "back": "F = ke \u2014 The restoring force of a spring is directly proportional to its extension, within the elastic limit. k = spring constant (N/m)."}, {"id": 28, "subject": "Chemistry", "front": "Graham's Law of Diffusion", "back": "Rate\u2081/Rate\u2082 = \u221a(M\u2082/M\u2081). The rate of diffusion of a gas is inversely proportional to the square root of its molar mass."}, {"id": 29, "subject": "Chemistry", "front": "General formula of alkanes, alkenes, alkynes", "back": "Alkanes: C\u2099H\u2082\u2099\u208a\u2082 (saturated), Alkenes: C\u2099H\u2082\u2099 (unsaturated, C=C), Alkynes: C\u2099H\u2082\u2099\u208b\u2082 (unsaturated, C\u2261C)."}, {"id": 30, "subject": "Biology", "front": "Functions of the human heart", "back": "The heart pumps blood through the body. Right side: deoxygenated blood to lungs. Left side: oxygenated blood to body. Beats ~72 times per minute."}]};
